ALTER TABLE "site_settings" ADD CONSTRAINT "site_settings_value_by_type_check" CHECK (("site_settings"."type"::text in ('image', 'video') and "site_settings"."value" is not null and char_length(trim("site_settings"."value")) > 0 and "site_settings"."image_urls" is null) or ("site_settings"."type"::text in ('text', 'plain_text') and "site_settings"."value" is null and "site_settings"."image_urls" is null) or ("site_settings"."type"::text = 'images' and "site_settings"."value" is null and "site_settings"."image_urls" is not null and cardinality("site_settings"."image_urls") > 0 and array_ndims("site_settings"."image_urls") = 1 and array_position("site_settings"."image_urls", null) is null and array_position("site_settings"."image_urls", '') is null));